async () => {
  const out = [];
  let doc = document;
  for (let p = 1; p <= 17; p++) {
    let d = doc;
    if (p > 1) {
      const form = document.forms[0];
      const fd = new FormData(form);
      fd.set('__EVENTTARGET', 'gv'); fd.set('__EVENTARGUMENT', 'Page$' + p);
      const r = await fetch(location.href, {method:'POST', body: new URLSearchParams(fd)});
      d = new DOMParser().parseFromString(await r.text(), 'text/html');
    }
    for (const tr of d.querySelectorAll('table tr')) {
      const c = [...tr.children].map(x => x.textContent.trim());
      if (c.length === 5 && /^D\d+/.test(c[1])) out.push(c.slice(0,4).join('|'));
    }
  }
  return out.filter(s => /\|(1004|1011|1026)\|/.test(s)).concat(['total ' + out.length]);
}

