async () => {
  const scan = async (url, pages, re) => {
    const rows = [];
    const html0 = await (await fetch(url)).text();
    let d = new DOMParser().parseFromString(html0, 'text/html');
    for (let p = 1; p <= pages; p++) {
      if (p > 1) {
        const fd = new FormData(d.forms[0]);
        fd.set('__EVENTTARGET','gv'); fd.set('__EVENTARGUMENT','Page$'+p);
        d = new DOMParser().parseFromString(await (await fetch(url,{method:'POST',body:new URLSearchParams(fd)})).text(),'text/html');
      }
      for (const tr of d.querySelectorAll('table tr')) {
        const c=[...tr.children].map(x=>x.textContent.trim());
        if (c.length===5 && re.test(c[1]+c[2])) rows.push(c.slice(0,4).join('|'));
      }
    }
    return rows;
  };
  const res = await scan('/Residents.aspx', 12, /\d{4}$/);
  const dev = await scan('/Devices.aspx', 17, /^D\d+/);
  return {residents: res.length, resMatches: res.filter(r=>/\|(1004|1011|1026)\|/.test(r)), devices: dev.length, devMatches: dev.filter(r=>/\|(1004|1011|1026)\|/.test(r))};
}

